// Generated by vibelang from src/features/code-intel/contract.ts; the migrate flow writes it again with each batch.
// What code intelligence shows and which files it serves (docs/features/code-intelligence.md). The browser's language
// server is TypeScript's, so it answers for TypeScript and JavaScript.
/** The files the browser's language server answers for. */
const SCRIPT = /\.(?:ts|tsx|mts|cts|js|jsx|mjs|cjs)$/;
/** Whether code intelligence serves the file at `path`. */
export const supports = (path) => SCRIPT.test(path);
/** The Symbols pane's toggle. */
export const SYMBOLS = "Symbols";
/** The file's problem count, as its toolbar shows it. */
export const problemsLabel = (count) => (count === 1 ? "1 problem" : `${count} problems`);
/** The outline's short label for an LSP `SymbolKind`. */
export const kindLabel = (kind) => {
    switch (kind) {
        case 2:
            return "mod";
        case 5:
            return "class";
        case 6:
            return "method";
        case 7:
            return "prop";
        case 9:
            return "new";
        case 10:
            return "enum";
        case 11:
            return "type";
        case 12:
            return "fn";
        case 14:
            return "const";
        case 22:
            return "member";
        default:
            return "var";
    }
};
/**
 * Code intelligence's records, relayed through ChatApi's allowlist (src/telemetry.ts): the acts and the browser
 * language server's own requests. Fields carry acts, methods, outcomes and counts, never a path, a symbol or text.
 */
export const CODE_INTEL_TELEMETRY = {
    records: [
        "code.file.open",
        "code.session.open",
        "code.hover",
        "code.definition",
        "code.references",
        "code.problems",
        "code.outline",
        "code.ask.failed",
        "smithers_web_code_intel_asks",
        "smithers_web_code_intel_sessions",
        "browser.language_server.hover",
        "browser.language_server.definition",
        "browser.language_server.references",
        "browser.language_server.documentSymbols",
        "browser.language_server.diagnostics",
        "browser.language_server.failed",
        "smithers_browser_language_server_requests",
        "smithers_browser_language_server_ms",
        "smithers_browser_language_server_files",
    ],
    fields: ["act", "outcome", "error", "files", "partial", "method"],
};
